// src/frontend/js/modern/modules/save-for-later/actions.js
import { BaseModule } from '../../shared/module-base.js';
import { eventBus, EVENTS } from '../../core/event-bus.js';
import { queueManager } from '../../core/queue.js';
import { fragmentManager } from '../../core/fragment-manager.js';
import saveForLaterUI from './ui.js';
import { showError, showSuccess, triggerBodyEvent } from '../../shared/ui-helpers.js';
import { loadAutomations } from '../../shared/api-helpers.js';
import { ScopeHelper } from '../../shared/scope-helpers.js';
import validators from '../../shared/validators.js';
import { ensurejQuery } from "../../shared/ui-helpers";

class SaveForLaterActions extends BaseModule {
	constructor() {
		super('saveForLater', null, null, saveForLaterUI);
	}

	async addWithFullData(cartItemKey, element = null, formData = null, options = {}) {
		const actionId = `sfl_add_${cartItemKey}_${Date.now()}`;
		const scope = ScopeHelper.sfl(cartItemKey);
		return this.executeWithConflictManagement(
			scope,
			actionId,
			null,
			null,
			() => {
				let data = formData;
				if (!data) {
					data = new FormData();
					data.append('add_to_save_for_later', cartItemKey);
					data.append('context', 'frontend');
					data.append('nonce', window.wlfmc_l10n?.ajax_nonce?.add_to_save_for_later_nonce);
					data.append(
						'merge_save_for_later',
						window.wlfmc_l10n?.merge_save_for_later ? '1' : '0'
					);
					data.append(
						'remove_from_cart_item',
						window.wlfmc_l10n?.remove_from_cart_item ? '1' : '0'
					);
					if (options.merge_save_for_later) data.append('merge_save_for_later', '1');
					if (options.remove_from_cart_item) data.append('remove_from_cart_item', '1');
				}
				data.delete('action');
				data.append('_scope', scope);
				return queueManager.addWithDeduplication('add_to_save_for_later', data);
			},
			(result) => this._handleAddSuccess(cartItemKey, result),
			(error) => this._handleAddError(cartItemKey, error),
			{ type: 'add', productId: cartItemKey, element: element }
		);
	}

	async addFromHandler(cartItemKey, formData, element = null) {
		const actionId = `sfl_add_${cartItemKey}_${Date.now()}`;
		const scope = ScopeHelper.sfl(cartItemKey);
		return this.executeWithConflictManagement(
			scope,
			actionId,
			null,
			null,
			() => queueManager.addWithDeduplication('add_to_save_for_later', formData),
			(result) => this._handleAddSuccess(cartItemKey, result),
			(error) => this._handleAddError(cartItemKey, error),
			{ type: 'add', productId: cartItemKey, element: element }
		);
	}

	async remove(itemId, nonce = '', element = null) {
		const actionId = `sfl_remove_${itemId}_${Date.now()}`;
		const scope = `sfl::item::${itemId}`;
		return this.executeWithConflictManagement(
			scope,
			actionId,
			null,
			null,
			() => queueManager.addWithDeduplication('remove_from_save_for_later', {
				remove_from_save_for_later: itemId,
				nonce: window.wlfmc_l10n?.ajax_nonce?.remove_from_save_for_later_nonce,
				context: 'frontend',
				_scope: scope,
			}),
			(result) => {
				this._handleRemoveSuccess(itemId, result);
			},
			(error) => {
				this._handleRemoveError(itemId, error);
			},
			{ type: 'remove', productId: itemId, element: element }
		);
	}

	async removeFromHandler(itemId, nonce, element) {
		return this.remove(itemId, nonce, element);
	}

	async addAllFromHandler(nonce) {
		try {
			const result = await queueManager.addWithDeduplication('add_all_to_save_for_later', {
				nonce: nonce,
			});
			if (result.message) {
				showError(result.message);
			}
			return result;
		} catch (error) {
			if (error.message) {
				showError(error.message);
			}
		}
	}

	/* ═══════════════════════════════════════════
	   SUCCESS HANDLERS — Confirm state + side effects.
	════════════════════════════════════════════ */
	_handleAddSuccess(cartItemKey, result) {
		if (!result) return;
		if (!validators.isTrue(result.result)) {
			if (result.message && String(result.message).trim() !== '') {
				showError(result.message);
			}
			return;
		}

		const addedText = window.wlfmc_l10n?.labels?.sfl_product_added_text;
		if (addedText && addedText.trim()) showSuccess(addedText);

		const mergeSaveForLater = validators.isTrue(window.wlfmc_l10n?.merge_save_for_later);
		const mergeLists = validators.isTrue(window.wlfmc_l10n?.merge_lists);
		const removeFromCart = validators.isTrue(window.wlfmc_l10n?.remove_from_cart_item);
		if (result.wishlist_id && result.customer_id && result.load_automation_nonce) {
			const automationListType = mergeSaveForLater
				? (mergeLists ? 'lists' : 'wishlist')
				: 'save-for-later';
			loadAutomations(
				result.product_id, result.wishlist_id, result.customer_id,
				automationListType, result.load_automation_nonce
			);
		}

		// Update tabs data-count from server response (legacy behavior)
		this.ui.updateTabsDataCount(result.count);

		// FIX: Load SFL tab fragment whenever SFL is NOT merged into wishlist.
		// The previous condition (!mergeLists && !mergeSaveForLater) was too
		// restrictive — it skipped fragment loading when mergeLists was true
		// even though SFL was displayed in its own tab.
		// Legacy always called load_fragments() unconditionally on success.
		if (!mergeSaveForLater) {
			this.ui.showTabLoader();
			// Hide the tab loader once fragments are fully replaced.
			fragmentManager.loadFragments({ s: 'save_for_later' }, () => {
				this.ui.hideTabLoader();
			});
		}
		if (mergeSaveForLater && removeFromCart || (!mergeLists && !mergeSaveForLater)) {
		triggerBodyEvent('wc_update_cart');
		}
		eventBus.emit(EVENTS.SAVE_FOR_LATER_ADDED, { cartItemKey, status: 'success', data: result });
	}

	_handleAddError(cartItemKey, error) {
		if (error.message) {
			showError(error.message);
		}
		eventBus.emit(EVENTS.SAVE_FOR_LATER_ADDED, { cartItemKey, status: 'failed', error: error.message });
	}

	_handleRemoveSuccess(itemId, result) {
		const removedText = window.wlfmc_l10n?.labels?.sfl_product_removed_text;
		if (removedText && removedText.trim()) showError(removedText);
		// Update tabs data-count from server response
		this.ui.updateTabsDataCount(result?.count);
		fragmentManager.loadFragments({ s: 'save_for_later' });
		// Legacy: if count is 0, empty the table wrapper
		if (result && result.count !== undefined && Number(result.count) === 0) {
			this.ui.clearEmptyTableWrapper();
		}
		const jQuery = window.jQuery;
		if (jQuery) {
			const button = document.querySelector(`.wlfmc_remove_from_save_for_later[data-item-id="${itemId}"]`);
			const row = button?.closest('[data-item-id]');
			jQuery(document.body).trigger('wlfmc_removed_from_save_for_later', [ensurejQuery(button), ensurejQuery(row), result]);
		}
		eventBus.emit(EVENTS.SAVE_FOR_LATER_REMOVED, { itemId, status: 'success', data: result });
	}

	_handleRemoveError(itemId, error) {
		if (error.message) {
			showError(error.message);
		}
		eventBus.emit(EVENTS.SAVE_FOR_LATER_REMOVED, { itemId, status: 'failed', error: error.message });
	}
}

export const saveForLaterActions = new SaveForLaterActions();
export default saveForLaterActions;
