// src/frontend/js/modern/entry-premium.js
import { createModernSystem } from './system.js';
import wishlistModule from './modules/wishlist/index.js';
import waitlistModule from './modules/waitlist/index.js';
import multiListModule from './modules/multi-list/index.js';
import saveForLaterModule from './modules/save-for-later/index.js';

const modernSystem = createModernSystem([
	wishlistModule,
	waitlistModule,
	multiListModule,
	saveForLaterModule,
]);

document.addEventListener('DOMContentLoaded', () => {
	modernSystem.init({ premium: true });
});

export default modernSystem;
