// src/frontend/js/modern/modules/waitlist/variation-controller.js
import { validators } from '../../shared/validators.js';

export function checkWaitlistModules(data, productId, variationId, store) {
	if (!productId || !variationId) return;

	let productType = 'variation';
	if (!data) {
		variationId = productId;
		productType = 'variable';
	}

	const l10n = window.wlfmc_l10n || {};
	const waitlistItems = store.items.get();

	// ===== Part 1: out-of-stock boxes =====
	const targetBoxes = document.querySelectorAll(
		`.wlfmc-add-to-outofstock [data-parent-product-id="${productId}"]`
	);

	targetBoxes.forEach(t => {
		const container = t.closest('.wlfmc-add-to-outofstock');
		if (!container) return;

		t.setAttribute('data-parent-product-id', String(productId));
		t.setAttribute('data-product-id', String(variationId));

		// FIX: Use \d+ to only replace the numeric ID class, preserving classes like '-loop'
		container.className = container.className.replace(
			/wlfmc-add-to-outofstock-\d+/g,
			`wlfmc-add-to-outofstock-${variationId}`
		);
		container.classList.remove('exists');

		let outofstockbox = document.querySelector(`.wlfmc-add-to-outofstock-${variationId}`);
		if (!outofstockbox) {
			outofstockbox = document.querySelector(`.wlfmc-add-to-outofstock-${productId}`);
		}

		if (outofstockbox) {
			if (data !== null) {
				if (data.wlfmc_hide_back_in_stock || validators.isTrue(data.exclude_back_in_stock)) {
					outofstockbox.classList.add('hide');
				} else {
					outofstockbox.classList.remove('hide');
				}
			} else {
				const outOfStock = outofstockbox.dataset.productOutofstock || outofstockbox.getAttribute('data-product-outofstock');
				if (validators.isTrue(outOfStock)) {
					outofstockbox.classList.remove('hide');
				} else {
					outofstockbox.classList.add('hide');
				}
			}

			let hasBackInStock = false;
			waitlistItems.forEach(v => {
				if (v.product_id && String(v.product_id) === String(variationId)) {
					if (validators.isTrue(v.back_in_stock)) {
						hasBackInStock = true;
					}
				}
			});

			if (hasBackInStock) {
				outofstockbox.classList.add('exists');
			} else {
				outofstockbox.classList.remove('exists');
			}

			// FIX: Also update the loop trigger wrapper if it exists for this variation
			document.querySelectorAll('.wlfmc-outofstock-popup-trigger').forEach(trigger => {
				const popupTrigger = trigger.querySelector('.wlfmc-popup-trigger');
				if (popupTrigger) {
					const popupId = popupTrigger.dataset.popupId || '';
					if (popupId && popupId.endsWith(`_${variationId}`)) {
						trigger.classList.toggle('exists', hasBackInStock);
					}
				}
			});

			const addBtn = outofstockbox.querySelector('.wlfmc-add-button > a');
			if (addBtn) {
				addBtn.setAttribute('data-parent-product-id', String(productId));
				addBtn.setAttribute('data-product-id', String(variationId));
				addBtn.setAttribute('data-product-type', productType);
			}
		}
	});

	// ===== Part 2: waitlist popup checkboxes =====
	const targets = document.querySelectorAll(
		`.wlfmc-add-to-waitlist [data-parent-product-id="${productId}"]`
	);

	targets.forEach(t => {
		const container = t.closest('.wlfmc-add-to-waitlist');
		if (!container) return;

		const popupId = container.dataset.popupId || container.getAttribute('data-popup-id');
		const popup = popupId ? document.getElementById(popupId) : null;

		const backinstockCheckbox = popup ? popup.querySelector('input[name="list_back-in-stock"]') : null;
		const pricechangeCheckbox = popup ? popup.querySelector('input[name="list_price-change"]') : null;
		const lowstockCheckbox = popup ? popup.querySelector('input[name="list_low-stock"]') : null;
		const onsaleCheckbox = popup ? popup.querySelector('input[name="list_on-sale"]') : null;

		const availableModules = (() => {
			const raw = container.dataset.availableLists || container.getAttribute('data-available-lists');
			if (!raw) return {};
			if (typeof raw === 'object') return raw;
			try {
				const parsed = JSON.parse(raw);
				if (Array.isArray(parsed)) {
					return parsed.reduce((acc, key) => ({ ...acc, [key]: true }), {});
				}
				return typeof parsed === 'object' && parsed !== null ? parsed : {};
			} catch (e) {
				return String(raw).split(',').reduce((acc, key) => ({ ...acc, [key.trim()]: true }), {});
			}
		})();

		container.classList.remove('opacity-half');

		if (data) {
			if (data.is_in_stock) {
				if (lowstockCheckbox) {
					if (data.enable_low_stock && validators.isTrue(data.enable_low_stock) && !validators.isTrue(data.exclude_low_stock)) {
						lowstockCheckbox.closest('.list-item')?.classList.remove('hide');
					} else {
						lowstockCheckbox.closest('.list-item')?.classList.add('hide');
					}
				}
				if (pricechangeCheckbox) {
					if (validators.isTrue(data.exclude_price_change)) {
						pricechangeCheckbox.closest('.list-item')?.classList.add('hide');
					} else {
						pricechangeCheckbox.closest('.list-item')?.classList.remove('hide');
					}
				}
				if (backinstockCheckbox) {
					if (data.wlfmc_hide_back_in_stock) {
						backinstockCheckbox.closest('.list-item')?.classList.add('hide');
					} else {
						backinstockCheckbox.closest('.list-item')?.classList.remove('hide');
					}
				}
				if (onsaleCheckbox) {
					if (data.display_price !== data.display_regular_price || validators.isTrue(data.exclude_on_sale)) {
						onsaleCheckbox.closest('.list-item')?.classList.add('hide');
					} else {
						onsaleCheckbox.closest('.list-item')?.classList.remove('hide');
					}
				}
				if (popup && !popup.querySelector('.wlfmc-waitlist-select-type .list-item:not(.hide)')) {
					container.classList.add('opacity-half');
				}
			} else if (typeof availableModules === 'object' && 'back-in-stock' in availableModules && !validators.isTrue(data.exclude_back_in_stock)) {
				if (backinstockCheckbox) backinstockCheckbox.closest('.list-item')?.classList.remove('hide');
				if (pricechangeCheckbox) pricechangeCheckbox.closest('.list-item')?.classList.add('hide');
				if (lowstockCheckbox) lowstockCheckbox.closest('.list-item')?.classList.add('hide');
				if (onsaleCheckbox) onsaleCheckbox.closest('.list-item')?.classList.add('hide');
			} else {
				container.classList.add('opacity-half');
			}
		}

		t.setAttribute('data-parent-product-id', String(productId));
		t.setAttribute('data-product-id', String(variationId));

		if (popup) {
			popup.querySelectorAll('input[name="list_back-in-stock"], input[name="list_price-change"], input[name="list_on-sale"], input[name="list_low-stock"]').forEach(cb => {
				cb.checked = false;
			});
		}

		// FIX: Use \d+ to only replace the numeric ID class
		container.className = container.className.replace(
			/wlfmc-add-to-waitlist-\d+/g,
			`wlfmc-add-to-waitlist-${variationId}`
		);
		container.classList.remove('exists');

		waitlistItems.forEach(v => {
			if (v.product_id && String(v.product_id) === String(variationId)) {
				if (
					validators.isTrue(v.price_change) ||
					validators.isTrue(v.on_sale) ||
					validators.isTrue(v.low_stock) ||
					(validators.isTrue(v.back_in_stock) && backinstockCheckbox)
				) {
					container.classList.add('exists');
				}

				if (popup) {
					if (validators.isTrue(v.back_in_stock)) {
						const cb = popup.querySelector('input[name="list_back-in-stock"]');
						if (cb) cb.checked = true;
					}
					if (validators.isTrue(v.price_change)) {
						const cb = popup.querySelector('input[name="list_price-change"]');
						if (cb) cb.checked = true;
					}
					if (validators.isTrue(v.on_sale)) {
						const cb = popup.querySelector('input[name="list_on-sale"]');
						if (cb) cb.checked = true;
					}
					if (validators.isTrue(v.low_stock)) {
						const cb = popup.querySelector('input[name="list_low-stock"]');
						if (cb) cb.checked = true;
					}
				}
			}
		});

		if (popup) {
			const submitBtn = popup.querySelector('.wlfmc_add_to_waitlist');
			if (submitBtn) {
				submitBtn.setAttribute('data-parent-product-id', String(productId));
				submitBtn.setAttribute('data-product-id', String(variationId));
				submitBtn.setAttribute('data-product-type', productType);
			}
		}

		if (productType === 'variable' && validators.isTrue(l10n.waitlist_required_product_variation)) {
			container.querySelectorAll('.wlfmc-popup-trigger').forEach(trigger => trigger.classList.add('wlfmc-disabled'));
		} else {
			container.querySelectorAll('.wlfmc-popup-trigger').forEach(trigger => trigger.classList.remove('wlfmc-disabled'));
		}
	});
}

export default checkWaitlistModules;
