// src/frontend/js/modern/modules/waitlist/actions.js

import { BaseModule } from '../../shared/module-base.js';
import { eventBus, EVENTS } from '../../core/event-bus.js';
import { queueManager } from '../../core/queue.js';
import { conflictManager } from '../../core/conflict-manager.js';
import waitlistModuleStore from './store.js';
import waitlistUI from './ui.js';
import { showError, showSuccess } from '../../shared/ui-helpers.js';
import { loadAutomations } from '../../shared/api-helpers.js';
import { ScopeHelper } from '../../shared/scope-helpers.js';
import { hidePopup } from '../../lib/popup-lite.js';
import { ensurejQuery } from "../../shared/ui-helpers";
import { fragmentManager } from '../../core/fragment-manager.js';

class WaitlistActions extends BaseModule {
	constructor() {
		super('waitlist', waitlistModuleStore, null, waitlistUI);
	}

	async addFromHandler(productId, formData, options = {}) {
		const actionId = `waitlist_add_${productId}_${Date.now()}`;
		const scope = ScopeHelper.waitlist(productId);
		const snapshot = this.snapshotItem(productId);
		const isNewItem = !snapshot.item;

		// Track the optimistic toast so rollbackFn can dismiss it on failure.
		let successToastEl = null;

		return this.executeWithConflictManagement(
			scope,
			actionId,
			() => {
				this._optimisticAdd(productId, options);
				if (options.element) {
					const popup = options.element.closest('.wlfmc-popup');
					if (popup) {
						hidePopup(popup);
					}
				}
				// Optimistic toast — shown BEFORE server response
				successToastEl = showSuccess(
					isNewItem
						? window.wlfmc_l10n?.labels?.waitlist_product_added
						: window.wlfmc_l10n?.labels?.waitlist_product_changed
				);
			},
			() => {
				if (snapshot.item) {
					this.store.updateItem(productId, snapshot.item);
					this.ui.updateButton(productId, { state: 'added', ...snapshot.item });
				} else {
					this._optimisticRemove(productId);
				}
				// Dismiss the optimistic success toast on rollback
				if (successToastEl && window.wlfmc_toastr) {
					window.wlfmc_toastr.clear(successToastEl, { force: true });
					successToastEl = null;
				}
			},
			() => queueManager.addWithDeduplication('add_to_waitlist', formData),
			(result) => this._handleAddSuccess(productId, result),
			(error) => this._handleAddError(productId, error),
			{
				type: 'add',
				productId,
				element: options?.element,
				// Data-only callback: when a REMOVE is already pending and
				// this ADD response arrives, persist the server-confirmed
				// identity so the REMOVE can send correct wishlist_id / nonce.
				// No UI side-effects here.
				onDataOnly: (result) => {
					if (result) {
						conflictManager.storeIdentity(scope, {
							wishlist_id: result.wishlist_id || null,
							remove_nonce: result.remove_nonce || result.nonce || '',
							wishlist_token: result.wishlist_token || '',
						});
					}
				}
			}
		);
	}

	async remove(productId, wishlistId = 0, nonce = '', element) {
		const pid = parseInt(productId, 10);
		const actionId = `waitlist_remove_${productId}_${Date.now()}`;
		const scope = ScopeHelper.waitlist(productId);
		const snapshot = this.snapshotItem(pid);

		// Track the optimistic toast so rollbackFn can dismiss it on failure.
		let removedToastEl = null;

		return this.executeWithConflictManagement(
			scope,
			actionId,
			() => {
				this._optimisticRemove(pid);
				if (element) {
					const popup = element.closest('.wlfmc-popup');
					if (popup) {
						hidePopup(popup);
					}
				}
				// Optimistic toast — shown BEFORE server response
				removedToastEl = showError(window.wlfmc_l10n?.labels?.waitlist_product_removed);
			},
			() => {
				if (snapshot.item) {
					this.store.updateItem(pid, snapshot.item);
					this.ui.updateButton(pid, { state: 'added', ...snapshot.item });
				}
				// Dismiss the optimistic removal toast on rollback
				if (removedToastEl && window.wlfmc_toastr) {
					window.wlfmc_toastr.clear(removedToastEl, { force: true });
					removedToastEl = null;
				}
			},
			() => {
				// Resolve identity at execution time. Because operations are
				// serialized per scope, by the time this serverFn runs the
				// preceding ADD (if any) has already completed and its
				// identity has been stored via onDataOnly.
				const identity = conflictManager.getIdentity(scope);
				const resolvedWishlistId = identity?.wishlist_id || wishlistId;
				const resolvedNonce = identity?.remove_nonce || nonce;

				// Consume the identity so it does not leak into future ops.
				if (identity) conflictManager.clearIdentity(scope);

				return queueManager.addWithDeduplication('remove_from_waitlist', {
					product_id: productId,
					remove_from_wishlist: productId,
					wishlist_id: resolvedWishlistId,
					nonce: resolvedNonce,
					_scope: scope,
				});
			},
			(result) => this._handleRemoveSuccess(pid, result),
			(error) => this._handleRemoveError(pid, error),
			{ type: 'remove', productId: pid, element: element }
		);
	}

	async cancelOutofstock(productId, productType = 'simple', element = null) {
		const actionId = `outofstock_cancel_${productId}_${Date.now()}`;
		const scope = ScopeHelper.waitlist(productId);
		const snapshot = this.snapshotItem(productId);

		// Track the optimistic toast so rollbackFn can dismiss it on failure.
		let removedToastEl = null;

		return this.executeWithConflictManagement(
			scope,
			actionId,
			() => {
				this._optimisticRemove(productId);
				if (element) {
					const popup = element.closest('.wlfmc-popup');
					if (popup) {
						hidePopup(popup);
					}
				}
				// Optimistic toast — shown BEFORE server response
				removedToastEl = showError(window.wlfmc_l10n?.labels?.waitlist_product_removed);
			},
			() => {
				if (snapshot.item) {
					this.store.updateItem(productId, snapshot.item);
					this.ui.updateButton(productId, { state: 'added', ...snapshot.item });
				}
				// Dismiss the optimistic removal toast on rollback
				if (removedToastEl && window.wlfmc_toastr) {
					window.wlfmc_toastr.clear(removedToastEl, { force: true });
					removedToastEl = null;
				}
			},
			() => {
				// Resolve identity at execution time (same rationale as remove).
				// cancelOutofstock sends add_to_waitlist with all flags set to 0,
				// which effectively unsubscribes the product. The server still
				// needs the correct wishlist_id to identify the subscription.
				const identity = conflictManager.getIdentity(scope);
				const resolvedWishlistId = identity?.wishlist_id || 0;
				if (identity) conflictManager.clearIdentity(scope);

				return queueManager.addWithDeduplication('add_to_waitlist', {
					action: 'wlfmc_add_product_to_waitlist',
					context: 'frontend',
					add_to_waitlist: String(productId),
					product_type: productType,
					on_sale: '0',
					back_in_stock: '0',
					price_change: '0',
					low_stock: '0',
					wishlist_id: resolvedWishlistId,
					_scope: scope,
				});
			},
			(result) => this._handleRemoveSuccess(productId, result),
			(error) => this._handleRemoveError(productId, error),
			{ type: 'remove', productId, element: element }
		);
	}

	/* ═══════════════════════════════════════════
	   OPTIMISTIC — State mutations ONLY.
	   Counter/list UI updates are handled reactively
	   by BaseListUI's stateCache subscription.
	════════════════════════════════════════════ */

	_optimisticAdd(productId, options = {}) {
		const { onSale = 0, backInStock = 0, priceChange = 0, lowStock = 0 } = options;
		const flags = {
			on_sale: onSale, back_in_stock: backInStock,
			price_change: priceChange, low_stock: lowStock,
		};
		const hasActiveFlags = onSale || backInStock || priceChange || lowStock;

		if (!hasActiveFlags) {
			this._optimisticRemove(productId);
			return;
		}

		if (this.store.hasItem(productId)) {
			this.store.updateItem(productId, { ...flags, _optimistic: true });
		} else {
			this.store.addItem(productId, flags);
		}
		this.ui.updateButton(productId, { state: 'added', ...flags });
	}

	_optimisticRemove(productId) {
		const pid = parseInt(productId, 10);
		if (this.store.hasItem(pid)) {
			this.store.removeItem(pid);
		}
		this.ui.updateButton(pid, { state: 'removed' });
	}

	/* ═══════════════════════════════════════════
	   SUCCESS / ERROR HANDLERS
	   All toast messages come from wlfmc_l10n.labels
	   (server-localized) or from error.message which
	   carries the server-translated message.
	════════════════════════════════════════════ */

	_handleAddSuccess(productId, result) {
		// Server returned state 'removed' — product was unsubscribed.
		if (result.state === 'removed') {
			if (this.store.hasItem(productId)) {
				this.store.removeItem(productId);
			}
			this._handleRemoveSuccess(productId, result);
			return;
		}

		if (!this.store.hasItem(productId)) {
			this.store.addItem(productId, {});
		}
		this.store.confirmAdd(productId, result);
		if (result.display) {
			this.store.setDisplayData(productId, result.display);
		}
		this.ui.updateButton(productId, { state: result.state || 'added' });

		if (result.wishlist_id && result.customer_id) {
			let listType = 'waitlist';
			if (result.on_sale) listType += ',on-sale';
			if (result.price_change) listType += ',price-change';
			if (result.back_in_stock) listType += ',back-in-stock';
			if (result.low_stock) listType += ',low-stock';
			loadAutomations(productId, result.wishlist_id, result.customer_id, listType, result.load_automation_nonce);
		}

		eventBus.emit(EVENTS.WAITLIST_ADDED, { productId, status: 'success', data: result });
	}

	_handleAddError(productId, error) {
		// error.message carries the server-translated message from the response.
		showError(error.message || window.wlfmc_l10n?.labels?.operation_failed);
		eventBus.emit(EVENTS.WAITLIST_ADDED, { productId, status: 'failed', error: error.message });
	}

	_handleRemoveSuccess(productId, result) {
		this.ui.updateButton(productId, { state: 'removed' });

		// Reload table fragment from server to remove the disabled row entirely.
		fragmentManager.loadFragments();
		const jQuery = window.jQuery;
		if (jQuery) {
			const button = document.querySelector(`.wlfmc_cancel_outofstock[data-product-id="${productId}"]`);
			const wrapper = document.querySelector(`.wlfmc-add-to-outofstock-${productId}`);
			jQuery(document.body).trigger('wlfmc_removed_from_waitlist', [ensurejQuery(button), ensurejQuery(wrapper), result]);
		}

		eventBus.emit(EVENTS.WAITLIST_REMOVED, { productId, status: 'success', data: result });
	}

	_handleRemoveError(productId, error) {
		// error.message carries the server-translated message from the response.
		showError(error.message || window.wlfmc_l10n?.labels?.operation_failed);
		eventBus.emit(EVENTS.WAITLIST_REMOVED, { productId, status: 'failed', error: error.message });
	}

	isInWaitlist(productId) {
		return this.store.hasItem(productId);
	}
}

export const waitlistActions = new WaitlistActions();
export default waitlistActions;
