// src/frontend/js/modern/modules/waitlist/index.js
import { eventManager } from '../../core/event-manager.js';
import { eventBus, EVENTS } from '../../core/event-bus.js';
import waitlistModuleStore from './store.js';
import waitlistActions from './actions.js';
import waitlistUI from './ui.js';
import { handleVariationShown, handleVariationReset, handleVariationHide } from '../../shared/variation-handler.js';
import { checkWaitlistModules } from './variation-controller.js';
import { showError } from '../../shared/ui-helpers.js';
import validators from '../../shared/validators.js';
import { applyModuleFilter } from '../../shared/filter-helpers.js';
import stateCache from "../../core/state-cache";
import {buildFormData, extractParentProductId, extractProductId} from "../../shared/dom-helpers";

function _checkCookies() {
	if (!validators.isCookieEnabled()) {
		window.alert(window.wlfmc_l10n?.labels?.cookie_disabled);
		return false;
	}
	return true;
}

function _validateWaitlistEmail(popup) {
	const emailField = popup ? popup.querySelector('input[name="wlfmc_email"]') : null;
	if (!emailField) return { valid: true, email: '' };

	const email = emailField.value.trim();
	if (email === '') {
		showError(window.wlfmc_l10n?.labels?.waitlist_email_required);
		return { valid: false, email };
	}
	if (!validators.isValidEmail(email)) {
		showError(window.wlfmc_l10n?.labels?.waitlist_email_format);
		return { valid: false, email };
	}
	return { valid: true, email };
}

const waitlistHandlers = [
	{
		selector: '.wlfmc_add_to_waitlist',
		eventName: 'click',
		handler: (event, element) => {
			const productId = extractProductId(element);
			if (!productId) return;
			if (!_checkCookies()) return;

			const parentProductId = extractParentProductId(element) || productId;
			const container = element.closest('.wlfmc-add-to-waitlist');
			const popup = element.closest('.wlfmc-popup');
			const { formData, quantity, productType } = buildFormData(element, productId, parentProductId);

			let onSale = 0, backInStock = 0, priceChange = 0, lowStock = 0, email = '';
			if (popup) {
				onSale = popup.querySelector('input[name="list_on-sale"]:checked') ? 1 : 0;
				backInStock = popup.querySelector('input[name="list_back-in-stock"]:checked') ? 1 : 0;
				priceChange = popup.querySelector('input[name="list_price-change"]:checked') ? 1 : 0;
				lowStock = popup.querySelector('input[name="list_low-stock"]:checked') ? 1 : 0;
				email = popup.querySelector('input[name="wlfmc_email"]')?.value?.trim() || '';
			} else if (container) {
				onSale = parseInt(container.dataset.onSale || 0, 10);
				backInStock = parseInt(container.dataset.backInStock || 0, 10);
				priceChange = parseInt(container.dataset.priceChange || 0, 10);
				lowStock = parseInt(container.dataset.lowStock || 0, 10);
			}

			const emailValidation = _validateWaitlistEmail(popup);
			if (!emailValidation.valid) return;
			email = emailValidation.email;

			if (!formData.has('add_to_waitlist')) formData.append('add_to_waitlist', String(productId));
			if (!formData.has('on_sale')) formData.append('on_sale', String(onSale));
			if (!formData.has('back_in_stock')) formData.append('back_in_stock', String(backInStock));
			if (!formData.has('price_change')) formData.append('price_change', String(priceChange));
			if (!formData.has('low_stock')) formData.append('low_stock', String(lowStock));
			if (email && !formData.has('wlfmc_email')) formData.append('wlfmc_email', email);
			if (!formData.has('product_type')) formData.append('product_type', productType);

			// Build filter data for third-party plugins
			const waitlistFilterData = {
				action: window.wlfmc_l10n?.actions?.add_to_waitlist_action,
				context: 'frontend',
				add_to_waitlist: productId,
				product_type: productType,
				parent_product_id: parentProductId,
				on_sale: onSale,
				back_in_stock: backInStock,
				price_change: priceChange,
				low_stock: lowStock,
				wlfmc_email: email,
			};

			// Third-party plugins may mutate waitlistFilterData in place OR return a new object.
			const filteredWaitlistData = applyModuleFilter('wlfmc_add_to_waitlist_data', element, waitlistFilterData);

			// Sync all keys — no reference inequality check (in-place mutation pattern).
			if (filteredWaitlistData && typeof filteredWaitlistData === 'object') {
				Object.entries(filteredWaitlistData).forEach(([key, value]) => {
					if (!formData.has(key)) {
						formData.append(key, typeof value === 'object' ? JSON.stringify(value) : String(value));
					}
				});
			}

			const jQuery = window.jQuery;
			if (jQuery) jQuery(document.body).trigger('wlfmc_adding_to_waitlist');

			waitlistActions.addFromHandler(productId, formData, {
				onSale, backInStock, priceChange, lowStock, email, element
			});
		},
		priority: 100,
	},
	{
		selector: '.wlfmc_add_to_outofstock:not(.wlfmc-waitlist-btn-login-need)',
		eventName: 'click',
		handler: (event, element) => {
			const productId = extractProductId(element);
			if (!productId) return;
			if (!_checkCookies()) return;

			const parentProductId = extractParentProductId(element) || productId;
			const container = element.closest('.wlfmc-add-to-outofstock');
			const { formData, quantity, productType } = buildFormData(element, productId, parentProductId);

			const emailField = container?.querySelector('input[name="wlfmc_email"]');
			const email = emailField ? emailField.value.trim() : '';

			if (emailField && email === '') {
				showError(window.wlfmc_l10n?.labels?.waitlist_email_required);
				return;
			}
			if (emailField && email !== '' && !validators.isValidEmail(email)) {
				showError(window.wlfmc_l10n?.labels?.waitlist_email_format);
				return;
			}

			if (!formData.has('add_to_waitlist')) formData.append('add_to_waitlist', String(productId));
			if (!formData.has('on_sale')) formData.append('on_sale', '0');
			if (!formData.has('back_in_stock')) formData.append('back_in_stock', '1');
			if (!formData.has('price_change')) formData.append('price_change', '0');
			if (!formData.has('low_stock')) formData.append('low_stock', '0');
			if (email && !formData.has('wlfmc_email')) formData.append('wlfmc_email', email);
			if (!formData.has('product_type')) formData.append('product_type', productType);

			const jQuery = window.jQuery;
			if (jQuery) jQuery(document.body).trigger('wlfmc_adding_to_waitlist');

			// UI updates are handled optimistically inside actions.js
			waitlistActions.addFromHandler(productId, formData, {
				onSale: 0, backInStock: 1, priceChange: 0, lowStock: 0, email, element, box : true
			});
		},
		priority: 90,
	},
	{
		selector: '.wlfmc_cancel_outofstock:not(.wlfmc-waitlist-btn-login-need)',
		eventName: 'click',
		handler: (event, element) => {
			const productId = extractProductId(element);
			if (!productId) return;
			if (!_checkCookies()) return;

			const productType = element.dataset.productType || 'simple';

			// UI updates are handled optimistically inside actions.js
			waitlistActions.cancelOutofstock(productId, productType, element);
		},
		priority: 90,
	},
	{
		selector: '.wlfmc-waitlist-btn-login-need',
		eventName: 'click',
		handler: (event) => {
			event.preventDefault();
			showError(window.wlfmc_l10n?.labels?.waitlist_login_need);
		},
		priority: 50,
	},
	{
		selector: '.wlfmc-add-to-waitlist .wlfmc-popup-trigger.wlfmc-disabled',
		eventName: 'click',
		handler: (event) => {
			event.preventDefault();
			showError(window.wlfmc_l10n?.labels?.waitlist_make_a_selection_text);
		},
		priority: 60,
	},
];

const waitlistModule = {
	name: 'waitlist',
	store: waitlistModuleStore,
	actions: waitlistActions,
	ui: waitlistUI,
	init() {
		eventManager.registerModuleHandlers('waitlist', waitlistHandlers);

		eventBus.on('variation:shown', (data) => {
			handleVariationShown(data, 'waitlist', waitlistModuleStore, waitlistUI);
			checkWaitlistModules(data, data.product_id, data.variation_id, waitlistModuleStore);
		});

		eventBus.on('variation:reset', (data) => {
			handleVariationReset(data.productId, 'waitlist', waitlistModuleStore, waitlistUI);
			checkWaitlistModules(null, data.productId, data.productId, waitlistModuleStore);
		});

		eventBus.on('variation:hide', (data) => {
			handleVariationHide(data.productId, 'waitlist', waitlistModuleStore, waitlistUI);
		});

		eventBus.on('store:sync-waitlist', (data) => {
			waitlistModuleStore.syncFromData(data);
			this.applyState();
		});

		eventBus.on('system:data-ready', () => this.applyState());

		eventBus.on(EVENTS.WAITLIST_ADDED, (data) => {
			if (data.fromOtherTab) this.applyState();
		});

		eventBus.on(EVENTS.WAITLIST_REMOVED, (data) => {
			if (data.fromOtherTab) this.applyState();
		});

		eventBus.on(EVENTS.SYNC_COMPLETED, () => this.applyState());

		eventBus.on('counter:remove', ({ isWishlist, productId, wishlistId, nonce, element = null }) => {
			if (isWishlist) return;
			const item = waitlistModuleStore.getItem(productId);
			waitlistActions.remove(
				productId,
				item?.wishlist_id || wishlistId || 0,
				item?.remove_nonce || nonce || '',
				element
			);
		});

		eventBus.on('cart:item_added_to_cart', ({ rowId, wishlistId, listType, isUserOwner }) => {
			if (listType !== 'waitlist' || !isUserOwner) return;
			waitlistActions.remove(rowId, wishlistId);
		});
	},
	applyState() {
		waitlistUI.syncPopupCheckboxes(stateCache.getItems('waitlist'));

	},
	getStatus() {
		return {
			count: waitlistModuleStore.count.get(),
			items: waitlistModuleStore.items.get().length,
		};
	},
};

export default waitlistModule;
export { waitlistModuleStore, waitlistActions, waitlistUI };
