// src/frontend/js/modern/modules/waitlist/ui.js

import { BaseListUI } from '../../shared/base-list-ui.js';
import { validators } from '../../shared/validators.js';
import waitlistModuleStore from './store.js';
import stateCache from "../../core/state-cache";

class WaitlistUI extends BaseListUI {
	constructor() {
		super({
			moduleName: 'waitlist',
			store: waitlistModuleStore,
			selectors: {
				addButton: '.wlfmc-add-to-waitlist',
				outofstockBox: '.wlfmc-add-to-outofstock',
				waitlistTable: '.wlfmc-waitlist-table',
				tableWrapper: '.wlfmc-waitlist-table-wrapper',
			}
		});
	}

	/* ═══════════════════════════════════════════
	   REACTIVE RENDER — Single Source of Truth
	   Overrides BaseListUI to also reconcile
	   waitlist buttons and out-of-stock boxes.
	════════════════════════════════════════════ */

	renderFromState() {
		const items = stateCache.getItems(this.moduleName);
		const count = stateCache.getCount(this.moduleName);
		this.syncCounterItems(items);
		this.updateCounter(count);
		this.syncAddButtons(items);

		this.syncPopupCheckboxes(items);

	}

	/**
	 * Reconcile all waitlist buttons and out-of-stock boxes with the
	 * current StateCache snapshot. Adds/removes the 'exists' class based
	 * on which notification flags are active for each product.
	 */
	syncAddButtons(items) {
		const itemMap = new Map();
		(items || []).forEach(item => {
			itemMap.set(String(item.product_id), item);
		});

		// Waitlist popup buttons
		document.querySelectorAll('.wlfmc-add-to-waitlist').forEach(el => {
			const cls = Array.from(el.classList).find(c => /^wlfmc-add-to-waitlist-\d+$/.test(c));
			const pid = cls ? cls.replace('wlfmc-add-to-waitlist-', '') : (el.dataset.productId || '');
			if (!pid) return;

			const item = itemMap.get(String(pid));
			const shouldBeExists = item && (
				validators.isTrue(item.price_change) ||
				validators.isTrue(item.on_sale) ||
				validators.isTrue(item.low_stock) ||
				validators.isTrue(item.back_in_stock)
			);
			const isCurrentlyExists = el.classList.contains('exists');

			if (shouldBeExists && !isCurrentlyExists) {
				el.classList.add('exists');
			} else if (!shouldBeExists && isCurrentlyExists) {
				el.classList.remove('exists');
			}
		});

		// Out-of-stock boxes (inner)
		document.querySelectorAll('.wlfmc-add-to-outofstock').forEach(el => {
			const cls = Array.from(el.classList).find(c => /^wlfmc-add-to-outofstock-\d+$/.test(c));
			const pid = cls ? cls.replace('wlfmc-add-to-outofstock-', '') : (
				el.dataset.productId ||
				el.dataset.product_id ||
				el.querySelector('[data-product-id]')?.dataset.productId ||
				el.querySelector('[data-product_id]')?.dataset.product_id ||
				''
			);
			if (!pid) return;

			const item = itemMap.get(String(pid));
			const shouldBeExists = item && validators.isTrue(item.back_in_stock);
			const isCurrentlyExists = el.classList.contains('exists');

			if (shouldBeExists && !isCurrentlyExists) {
				el.classList.add('exists');
			} else if (!shouldBeExists && isCurrentlyExists) {
				el.classList.remove('exists');
			}
		});

		// Out-of-stock loop triggers (outer)
		document.querySelectorAll('.wlfmc-outofstock-popup-trigger').forEach(trigger => {
			const pid = trigger.dataset.productId || trigger.getAttribute('data-product-id');
			if (!pid) return;

			const item = itemMap.get(String(pid));
			const shouldBeExists = item && validators.isTrue(item.back_in_stock);
			const isCurrentlyExists = trigger.classList.contains('exists');

			if (shouldBeExists && !isCurrentlyExists) {
				trigger.classList.add('exists');
			} else if (!shouldBeExists && isCurrentlyExists) {
				trigger.classList.remove('exists');
			}
		});
	}

	updateButton(productId, data = {}) {
		const selector = `.wlfmc-add-to-waitlist-${productId}`;
		document.querySelectorAll(selector).forEach((el) => {
			const state = data.state || 'added';
			if (state === 'added' || state === 'changed') {
				el.classList.add('exists');
			} else if (state === 'removed') {
				el.classList.remove('exists');
			}
		});

		const container = document.querySelector(selector);
		const popupId = container?.dataset.popupId || container?.getAttribute('data-popup-id');
		if (popupId) {
			const popupEl = document.getElementById(popupId);
			if (popupEl) {
				const setCb = (name, val) => {
					const cb = popupEl.querySelector(`input[name="${name}"]`);
					if (cb) cb.checked = validators.isTrue(val);
				};
				if (data.on_sale !== undefined) setCb('list_on-sale', data.on_sale);
				if (data.back_in_stock !== undefined) setCb('list_back-in-stock', data.back_in_stock);
				if (data.price_change !== undefined) setCb('list_price-change', data.price_change);
				if (data.low_stock !== undefined) setCb('list_low-stock', data.low_stock);
			}
		}

		this.updateOutofstockBox(productId);
	}

	updateOutofstockBox(productId) {
		const item = this.store.getItem(productId);
		const hasBackInStock = item && validators.isTrue(item.back_in_stock);

		document.querySelectorAll(`.wlfmc-add-to-outofstock-${productId}`).forEach((el) => {
			el.classList.toggle('exists', !!hasBackInStock);
		});

		document.querySelectorAll(`.wlfmc-outofstock-popup-trigger[data-product-id="${productId}"]`).forEach((trigger) => {
			trigger.classList.toggle('exists', !!hasBackInStock);
		});
	}

	updateRemoveButton(productId) {
		const selector = `.wlfmc-add-to-waitlist-${productId}`;
		document.querySelectorAll(selector).forEach((el) => { el.classList.remove('exists'); });
		this.updateOutofstockBox(productId);
	}

	/**
	 * Reconcile all waitlist popup checkboxes with the current state.
	 * When a product is removed from the counter, its popup checkboxes
	 * must be unchecked so the user sees the correct subscription state.
	 *
	 * @param {Array} items - Current waitlist items from StateCache
	 */
	syncPopupCheckboxes(items) {
		const itemMap = new Map();
		(items || []).forEach(item => {
			itemMap.set(String(item.product_id), item);
		});

		document.querySelectorAll('.wlfmc-add-to-waitlist').forEach(el => {
			const cls = Array.from(el.classList).find(c => /^wlfmc-add-to-waitlist-\d+$/.test(c));
			const pid = cls ? cls.replace('wlfmc-add-to-waitlist-', '') : (el.dataset.productId || '');
			if (!pid) return;

			const item = itemMap.get(String(pid));
			const popupId = el.dataset.popupId || el.getAttribute('data-popup-id');
			if (!popupId) return;

			const popup = document.getElementById(popupId);
			if (!popup) return;

			const setCb = (name, val) => {
				const cb = popup.querySelector(`input[name="${name}"]`);
				if (cb) cb.checked = item ? validators.isTrue(val) : false;
			};
			setCb('list_back-in-stock', item?.back_in_stock);
			setCb('list_price-change', item?.price_change);
			setCb('list_on-sale', item?.on_sale);
			setCb('list_low-stock', item?.low_stock);
		});
	}
}

export const waitlistUI = new WaitlistUI();
export default waitlistUI;
