// src/frontend/js/modern/modules/save-for-later/index.js
import { eventManager } from '../../core/event-manager.js';
import { eventBus, EVENTS } from '../../core/event-bus.js';
import { fragmentManager } from '../../core/fragment-manager.js';
import saveForLaterActions from './actions.js';
import saveForLaterUI from './ui.js';
import { showError, showSuccess, triggerBodyEvent } from '../../shared/ui-helpers.js';
import validators from '../../shared/validators.js';
import { showPopup, hidePopup } from '../../lib/popup-lite.js';
import { queueManager } from '../../core/queue.js';
import {
	shouldSendAddToCartRequest,
	triggerAddingToCart,
	triggerAddedToCartEvents,
	triggerAjaxRequestNotSent
} from '../../shared/cart-helpers.js';
import { getItemIdFromElement } from "../../shared/dom-helpers";

// Module-local state: stores the remove URL captured from cart remove link.
let _removeItemUrl = null;

/**
 * Unbind WooCommerce's default cart-remove handlers.
 * Without this, WooCommerce redirects BEFORE our popup handler can intercept.
 * Must run after WooCommerce has attached its handlers.
 */
function unbindWooCommerceRemoveHandlers() {
	const isSflEnabled = window.wlfmc_l10n?.is_save_for_later_enabled &&
		window.wlfmc_l10n?.is_save_for_later_popup_remove_enabled;
	if (!isSflEnabled) return;
	const jQuery = window.jQuery;
	if (jQuery) {
		jQuery('.woocommerce-cart-form .product-remove a.remove').off('click');
		const delegatedSelectors = [
			'a.remove',
			'.product-remove a.remove',
			'.woocommerce-cart-form .product-remove a.remove',
			'form.woocommerce-cart-form a.remove',
		];
		delegatedSelectors.forEach((sel) => {
			jQuery(document.body).off('click', sel);
			jQuery(document).off('click', sel);
		});
	}
}

const saveForLaterHandlers = [
	// Intercept WooCommerce cart remove link and show the SFL popup instead.
	{
		selector: 'form.woocommerce-cart-form a.remove',
		eventName: 'click',
		handler: (event, element) => {
			const isSflEnabled = window.wlfmc_l10n?.is_save_for_later_enabled &&
				window.wlfmc_l10n?.is_save_for_later_popup_remove_enabled;
			if (!isSflEnabled) return;
			event.preventDefault();
			event.stopImmediatePropagation();
			_removeItemUrl = element.getAttribute('href');
			const popup = document.getElementById('add_to_save_for_later_popup');
			if (!popup) {
				window.location.href = _removeItemUrl;
				return;
			}
			// Show popup ONLY. Button handlers below handle the user's choice.
			showPopup(popup);
		},
		priority: 100,
	},
	{
		selector: '.wlfmc_add_to_save_for_later',
		eventName: 'click',
		handler: (event, element) => {
			if (element.dataset.popupId) return;
			const cartItemKey = element.dataset.cartItemKey || element.getAttribute('data-cart_item_key');
			if (!cartItemKey) return;
			if (!validators.isCookieEnabled()) {
				window.alert(window.wlfmc_l10n?.labels?.cookie_disabled);
				return;
			}
			const formData = new FormData();
			formData.append('add_to_save_for_later', cartItemKey);
			formData.append('context', 'frontend');
			formData.append('nonce', window.wlfmc_l10n?.ajax_nonce?.add_to_save_for_later_nonce);
			formData.append('merge_save_for_later', window.wlfmc_l10n?.merge_save_for_later || '0');
			formData.append('remove_from_cart_item', window.wlfmc_l10n?.remove_from_cart_item || '0');
			saveForLaterActions.addFromHandler(cartItemKey, formData, element);
		},
		priority: 100,
	},
	{
		selector: '.wlfmc_remove_from_save_for_later',
		eventName: 'click',
		handler: (event, element) => {
			const itemId = getItemIdFromElement(element);
			if (!itemId) return;
			const nonce = window.wlfmc_l10n?.ajax_nonce?.remove_from_save_for_later_nonce;
			saveForLaterActions.removeFromHandler(itemId, nonce, element);
		},
		priority: 90,
	},
	{
		selector: '.wlfmc_save_for_later_ajax_add_to_cart',
		eventName: 'click',
		handler: (event, element) => {
			const itemId = getItemIdFromElement(element);
			if (!itemId) return;
			if (!shouldSendAddToCartRequest(element)) {
				triggerAjaxRequestNotSent(element);
				return;
			}
			saveForLaterUI.setAddToCartLoading(element);
			triggerAddingToCart(element, {});
			queueManager.addWithDeduplication('save_for_later_add_to_cart', {
				item_id: itemId,
				nonce:
					element.dataset.nonce ||
					window.wlfmc_l10n?.ajax_nonce?.add_to_cart_from_sfl_nonce,
			})
				.then((result) => {
					if (result.error) {
						showError(result.error);
						return;
					}
					saveForLaterUI.replaceMiniCartFragment(result.fragments);
					if (!document.querySelector('form.woocommerce-cart-form')) {
						location.reload();
						return;
					}
					if (result.fragments && result.fragments.wlfmc_save_for_later_count !== undefined) {
						saveForLaterUI.updateTabsDataCount(result.fragments.wlfmc_save_for_later_count);
					}
					triggerAddedToCartEvents(result.fragments, result.cart_hash, element);
				})
				.catch((error) => {
					showError(error.message);
				})
				.finally(() => saveForLaterUI.unsetAddToCartLoading(element));
		},
		priority: 80,
	},
	{
		selector: '.wlfmc_save_all_for_later_link',
		eventName: 'click',
		handler: (event, element) => {
			if (element.dataset.popupId) return;
			const nonce = element.dataset.nonce;
			saveForLaterActions.addAllFromHandler(nonce);
		},
		priority: 70,
	},
	{
		selector: '.wlfmc-sfl-btn-login-need',
		eventName: 'click',
		handler: (event) => {
			event.preventDefault();
			showError(window.wlfmc_l10n?.labels?.sfl_login_need);
		},
		priority: 50,
	},
	{
		selector: '.wlfmc-list .remove-all-from-save-for-later-btn',
		eventName: 'click',
		handler: (event, element) => {
			saveForLaterUI.disableFormQtyInputs(element);
		},
		priority: 70,
	},
	{
		selector: '.wlfmc-accordion-header',
		eventName: 'click',
		handler: (event, element) => {
			event.preventDefault();
			saveForLaterUI.toggleAccordionPanel(element);
		},
		priority: 60,
	},
	// Popup "Save for Later" button — adds item to SFL then hides popup.
	{
		selector: '#add_to_save_for_later_popup #add_item',
		eventName: 'click',
		handler: (event, element) => {
			event.preventDefault();
			if (!_removeItemUrl) return;
			const cartItemKey = validators.getUrlParameter(_removeItemUrl, 'remove_item');
			if (cartItemKey) {
				saveForLaterActions.addWithFullData(cartItemKey, element).then((result) => {
					saveForLaterUI.hideSflPopup();
				});
			}
		},
		priority: 80,
	},
	// Popup "Remove" button — proceeds with the original WooCommerce remove URL.
	{
		selector: '#add_to_save_for_later_popup #remove_item',
		eventName: 'click',
		handler: (event, element) => {
			event.preventDefault();
			saveForLaterUI.hideSflPopup();
			if (_removeItemUrl) {
				window.location.href = _removeItemUrl;
			}
		},
		priority: 80,
	},
];

const saveForLaterModule = {
	name: 'saveForLater',
	store: null,
	actions: saveForLaterActions,
	ui: saveForLaterUI,
	init() {
		const isSflRemoveEnabled = window.wlfmc_l10n?.is_save_for_later_enabled &&
			window.wlfmc_l10n?.is_save_for_later_popup_remove_enabled;
		const handlersToRegister = isSflRemoveEnabled
			? saveForLaterHandlers
			: saveForLaterHandlers.filter(h =>
				h.selector !== 'form.woocommerce-cart-form a.remove'
			);
		eventManager.registerModuleHandlers('saveForLater', handlersToRegister);
		if (isSflRemoveEnabled) {
			unbindWooCommerceRemoveHandlers();
		}
		eventBus.on('cart:sfl_item_added_to_cart', ({ itemId }) => {
			saveForLaterActions.remove(itemId).then(() => {
				const sflWrapper = document.querySelector('.wlfmc-save-for-later-table-wrapper');
				if (sflWrapper && !sflWrapper.querySelector('.wlfmc-save-for-later-items-wrapper tr')) {
					sflWrapper.innerHTML = '';
				}
			});
		});
	},
	applyState() {
		// All counter and button rendering is handled reactively by
		// SaveForLaterUI.renderFromState() via the stateCache subscription.
		// Save For Later has NO optimistic updates — state changes only
		// after server confirmation, so reactive rendering always shows
		// the confirmed truth.
	},
	getStatus() {
		return {
			count: 0,
			items: 0,
		};
	},
};

export default saveForLaterModule;
export { saveForLaterActions, saveForLaterUI };
