// src/frontend/js/modern/modules/save-for-later/ui.js
import { BaseListUI } from '../../shared/base-list-ui.js';
import { hidePopup } from '../../lib/popup-lite.js';

class SaveForLaterUI extends BaseListUI {
	constructor() {
		super({
			moduleName: 'saveForLater',
			store: null,
			selectors: {
				addButton: '.wlfmc-add-to-saveforlater',
				removeButton: '.wlfmc_remove_from_save_for_later',
				table: '.wlfmc-save-for-later-table',
				tableWrapper: '.wlfmc-save-for-later-table-wrapper',
				accordion: '.wlfmc-accordion',
				tab: '.wlfmc-tabs .nav-tab[data-content="save-for-later"]',
			}
		});
		this._popupId = 'add_to_save_for_later_popup';
	}

	/* ═══════════════════════════════════════════
	   TAB LOADER
	   Shows a small spinner next to the SFL tab title
	   while fragments are loading.
	════════════════════════════════════════════ */
	showTabLoader() {
		const tabs = document.querySelectorAll(this._selectors.tab);
		tabs.forEach(tab => {
			if (!tab || tab.querySelector('.wlfmc-tab-loader')) return;
			const loader = document.createElement('span');
			loader.className = 'wlfmc-tab-loader wlfmc-action wlfmc-loading-alt';
			tab.appendChild(loader);
		});
	}

	hideTabLoader() {
		document.querySelectorAll(
			`${this._selectors.tab} .wlfmc-tab-loader`
		).forEach(el => el.remove());
	}

	/* ═══════════════════════════════════════════
	   TABS DATA-COUNT
	   Updates the data-count attribute on all
	   .wlfmc-tabs-wrapper elements. The CSS uses
	   this attribute to show/hide the SFL tab.
	════════════════════════════════════════════ */
	updateTabsDataCount(count) {
		if (count === undefined || count === null) return;
		document.querySelectorAll('.wlfmc-tabs-wrapper').forEach(el => {
			el.setAttribute('data-count', String(count));
		});
	}

	/* ═══════════════════════════════════════════
	   EMPTY TABLE WRAPPER
	   Legacy: if count is 0, empty the table wrapper.
	════════════════════════════════════════════ */
	clearEmptyTableWrapper() {
		const wrapper = document.querySelector(this._selectors.tableWrapper);
		if (wrapper) wrapper.innerHTML = '';
	}

	/* ═══════════════════════════════════════════
	   MINI CART FRAGMENT
	   Replaces the WooCommerce mini cart widget
	   with the server-rendered fragment.
	════════════════════════════════════════════ */
	replaceMiniCartFragment(fragments) {
		if (!fragments) return;
		const miniCart = document.querySelector('div.widget_shopping_cart_content');
		if (miniCart && fragments['div.widget_shopping_cart_content']) {
			miniCart.outerHTML = fragments['div.widget_shopping_cart_content'];
		}
	}

	/* ═══════════════════════════════════════════
	   ADD TO CART BUTTON LOADING STATE
	════════════════════════════════════════════ */
	setAddToCartLoading(element) {
		if (!element) return;
		element.classList.remove('added');
		element.classList.add('loading');
	}

	unsetAddToCartLoading(element) {
		if (!element) return;
		element.classList.remove('loading');
	}

	/* ═══════════════════════════════════════════
	   ACCORDION PANEL TOGGLE
	   Legacy: $(this).next(".wlfmc-accordion-panel")
	   with slideDown / slideUp animation.
	════════════════════════════════════════════ */
	toggleAccordionPanel(element) {
		const panel = element.nextElementSibling;
		if (!panel || !panel.classList.contains('wlfmc-accordion-panel')) return;
		if (!element.classList.contains('active')) {
			element.classList.add('active');
			panel.style.display = 'block';
			panel.style.overflow = 'hidden';
			const height = panel.scrollHeight;
			panel.style.height = '0';
			panel.style.transition = 'height 0.3s ease';
			requestAnimationFrame(() => {
				panel.style.height = height + 'px';
			});
			setTimeout(() => {
				panel.style.height = '';
				panel.style.overflow = '';
			}, 300);
		} else {
			element.classList.remove('active');
			const height = panel.scrollHeight;
			panel.style.height = height + 'px';
			panel.style.overflow = 'hidden';
			panel.style.transition = 'height 0.3s ease';
			requestAnimationFrame(() => {
				panel.style.height = '0';
			});
			setTimeout(() => {
				panel.style.display = 'none';
				panel.style.height = '';
				panel.style.overflow = '';
			}, 300);
		}
	}

	openAccordion() {
		const header = document.querySelector(`${this._selectors.accordion} .wlfmc-accordion-header`);
		if (header && !header.classList.contains('active')) {
			header.dispatchEvent(new Event('click', { bubbles: true }));
		}
	}

	/* ═══════════════════════════════════════════
	   SFL POPUP
	════════════════════════════════════════════ */
	hideSflPopup() {
		const popup = document.getElementById(this._popupId);
		if (popup) hidePopup(popup);
	}

	/* ═══════════════════════════════════════════
	   FORM QTY INPUTS
	   Legacy: disable all qty inputs before
	   "remove all from save for later" submit.
	════════════════════════════════════════════ */
	disableFormQtyInputs(element) {
		const form = element?.closest('form');
		if (form) {
			form.querySelectorAll('input.qty').forEach(el => el.disabled = true);
		}
	}
}

export const saveForLaterUI = new SaveForLaterUI();
export default saveForLaterUI;
